/**
 * خدمة إدارة شرط طلب الرقم السري الرئيسي عند تغيير/اختيار المحفظة.
 * التخزين محلي عبر localStorage مع مفتاح يعتمد على معرف المستخدم عند توفره.
 */

const KEY_BASE = 'wallet_selection_pin_required';

function getKey(userId?: string) {
  return userId ? `${KEY_BASE}_${userId}` : KEY_BASE;
}

export const walletSelectionPinService = {
  isEnabled(userId?: string): boolean {
    try {
      const val = localStorage.getItem(getKey(userId));
      return val === 'true';
    } catch {
      return false;
    }
  },
  setEnabled(enabled: boolean, userId?: string): void {
    try {
      localStorage.setItem(getKey(userId), enabled ? 'true' : 'false');
    } catch {}
  },

  /**
   * دعم إعدادات إضافية مشابهة (features) باستخدام لاحقة في المفتاح.
   * مثال: feature = 'sales_protection' للتحكم في طلب الرقم السري في قسم المبيعات.
   */
  isFeatureEnabled(feature: string, userId?: string): boolean {
    try {
      const key = `${getKey(userId)}:${feature}`;
      const val = localStorage.getItem(key);
      return val === 'true';
    } catch {
      return false;
    }
  },
  setFeatureEnabled(feature: string, enabled: boolean, userId?: string): void {
    try {
      const key = `${getKey(userId)}:${feature}`;
      localStorage.setItem(key, enabled ? 'true' : 'false');
    } catch {}
  }
};